// Layered, time-based spell VFX. Cosmetic only: combat numbers remain in the game simulation.
let deluxeFX=[],effectQuality='high',currentImpactType=null;try{effectQuality=localStorage.getItem('ashen-fx')==='low'?'low':'high'}catch{}
const EFFECT_COLORS={fire:'#ff9c3d',frost:'#8be5ff',arc:'#b9bbff',cleave:'#ffe1a4',arrow:'#84f0ab',vortex:'#ae7fff',slash:'#f7d4a0',dash:'#9acbdc'};
function addEffect(type,x,y,extra={}){if(deluxeFX.length>100)deluxeFX.splice(0,deluxeFX.length-100);deluxeFX.push({type,x,y,time:0,duration:extra.duration||.65,seed:Math.random()*1000,...extra})}
function setEffectQuality(value){if(!['high','low'].includes(value))return false;if(effectQuality===value)return true;effectQuality=value;try{localStorage.setItem('ashen-fx',value)}catch{}if(typeof resize==='function')resize();return true;}
const effectsPerform=performAction;performAction=a=>{let type=a.n===0?'slash':p.bindings[skillBindingIndex(a.n)],before=shots.length,angle=Math.atan2(a.target.y-p.y,a.target.x-p.x);currentImpactType=type;try{effectsPerform(a)}finally{currentImpactType=null}for(let i=before;i<shots.length;i++){shots[i].skill=type;shots[i].trail=[]}if(type==='frost'){let b=skillBuild(type);addEffect('nova',p.x,p.y,{r:190*(b?.radius||1),duration:.85});shake=Math.max(shake,3)}else if(type==='slash'||type==='cleave'){addEffect('slash',p.x,p.y,{angle,r:type==='cleave'?145*(skillBuild(type)?.radius||1):100,duration:.32})}else if(type==='wind'){addEffect('sigil',p.x,p.y,{color:'#a5f0cc',r:210*(skillBuild(type)?.radius||1),duration:.7})}else if(type==='arc'){addEffect('sigil',p.x,p.y,{color:'#9daaff',r:55,duration:.4})}else if(type==='vortex'){addEffect('sigil',p.x,p.y,{color:'#b293e7',r:70,duration:.6})}else addEffect('muzzle',p.x+Math.cos(angle)*35,p.y+Math.sin(angle)*35,{color:EFFECT_COLORS[type],duration:.25})};
const effectsHit=hit;hit=(e,d)=>{let hp=e.hp;let incoming=shots.find(s=>!s.enemy&&dist(s,e)<45),type=currentImpactType||incoming?.skill||'slash';effectsHit(e,d);if(hp>e.hp){addEffect('impact',e.x,e.y,{color:incoming?.tint||EFFECT_COLORS[type]||'#e7cfaa',style:type,r:e.boss?85:48,duration:type==='fire'?.6:.4});if(e.hp<=0)addEffect('embers',e.x,e.y,{color:EFFECT_COLORS[type]||'#b68c65',duration:.9,r:65})}};
const effectsCast=cast;cast=n=>{let old=p?{x:p.x,y:p.y}:null;effectsCast(n);if(n===3&&old&&dist(old,p)>10){for(let j=0;j<5;j++)addEffect('ghost',old.x+(p.x-old.x)*j/5,old.y+(p.y-old.y)*j/5,{duration:.35+j*.035,facing:face});addEffect('sigil',p.x,p.y,{r:35,color:'#b3d9e9',duration:.25})}};
const effectsFloor=enterFloor;enterFloor=()=>{deluxeFX=[];effectsFloor()};
const effectsUpdate=update;update=dt=>{let running=started&&!paused;effectsUpdate(dt);if(!running)return;for(let e of deluxeFX)e.time+=dt;deluxeFX=deluxeFX.filter(e=>e.time<e.duration);for(let s of shots){s.trail??=[];s.trail.push({x:s.x,y:s.y});if(s.trail.length>12)s.trail.shift()}};
function glowAt(s,r,color,alpha=1){ctx.save();ctx.globalAlpha=alpha;let g=ctx.createRadialGradient(s.x,s.y,0,s.x,s.y,r);g.addColorStop(0,color);g.addColorStop(.2,color+'88');g.addColorStop(1,color+'00');circle(s.x,s.y,r,g);ctx.restore()}
function ringPoints(x,y,r,start,end,steps=40){ctx.beginPath();for(let i=0;i<=steps;i++){let a=start+(end-start)*i/steps,s=project(x+Math.cos(a)*r,y+Math.sin(a)*r);i?ctx.lineTo(s.x,s.y):ctx.moveTo(s.x,s.y)}}
function iceShard(x,y,size,angle,alpha){let s=project(x,y);ctx.save();ctx.translate(s.x,s.y);ctx.rotate(angle);ctx.globalAlpha=alpha;ctx.fillStyle='#538eaf';ctx.beginPath();ctx.moveTo(0,-size);ctx.lineTo(size*.24,0);ctx.lineTo(0,size*.35);ctx.lineTo(-size*.2,0);ctx.closePath();ctx.fill();ctx.strokeStyle='#b3e5f2';ctx.lineWidth=.65;ctx.stroke();ctx.restore()}
function paintDeluxeEffects(){if(!started||!p)return;let count=effectQuality==='low'?.45:1;ctx.save();ctx.globalCompositeOperation='lighter';
for(let s of shots){if(s.art==='windBlade'||s.art==='throwingKnife'||s.art==='woodArrow'||!visibleAt(s.x,s.y))continue;let col=s.enemy?'#c27aa9':s.tint||EFFECT_COLORS[s.skill]||'#ffab4d',pos=project(s.x,s.y);pos.y-=12;let trail=s.trail||[];if(trail.length>1){for(let j=1;j<trail.length;j++){let a=project(trail[j-1].x,trail[j-1].y),b=project(trail[j].x,trail[j].y);ctx.globalAlpha=j/trail.length*.7;ctx.strokeStyle=col;ctx.lineWidth=(s.skill==='arrow'?3:10)*j/trail.length;ctx.lineCap='round';ctx.beginPath();ctx.moveTo(a.x,a.y-12);ctx.lineTo(b.x,b.y-12);ctx.stroke()}}ctx.globalAlpha=1;glowAt(pos,s.enemy?22:38,col,.5);if(s.skill==='arrow'){ctx.strokeStyle='#d2ffb7';ctx.lineWidth=2;let tail=project(s.x-s.vx*.04,s.y-s.vy*.04);ctx.beginPath();ctx.moveTo(tail.x,tail.y-12);ctx.lineTo(pos.x,pos.y);ctx.stroke()}else{circle(pos.x,pos.y,5,'#fff4cf');for(let j=0;j<4*count;j++){let a=clock*12+j*1.7;circle(pos.x+Math.cos(a)*7,pos.y+Math.sin(a)*4,4,col)}}}
for(let e of deluxeFX){let t=e.time/e.duration,fade=1-t,s=project(e.x,e.y),col=e.color||'#9fddff';if(!visibleAt(e.x,e.y))continue;if(e.type==='nova'){let r=e.r*(.18+.82*(1-Math.pow(1-t,3)));ctx.globalAlpha=fade;for(let j=0;j<3;j++){ringPoints(e.x,e.y,r*(1-j*.045),0,Math.PI*2);ctx.strokeStyle=j===0?'#e4fcff':'#59c5ef';ctx.lineWidth=j===0?3:1;ctx.stroke()}let n=Math.floor(26*count);for(let j=0;j<n;j++){let a=j/n*Math.PI*2,rr=r*(.8+.15*Math.sin(j*4));iceShard(e.x+Math.cos(a)*rr,e.y+Math.sin(a)*rr,(10+Math.sin(j*17)*5)*fade,a,Math.min(.55,t*4)*fade)}glowAt(s,100,'#86d9ff',fade*.2)}
if(e.type==='slash'){let angle=e.angle-1.15+t*2.3;ctx.globalAlpha=fade;for(let j=0;j<5*count;j++){ringPoints(e.x,e.y,e.r-j*5,angle-.8,angle,20);ctx.lineWidth=8-j;ctx.strokeStyle=j<2?'#ffecd2':'#cd9d5d';ctx.stroke()}let tip=project(e.x+Math.cos(angle)*e.r,e.y+Math.sin(angle)*e.r);glowAt(tip,25,'#ffe7b4',fade)}
if(e.type==='impact'){let r=e.r*(.25+t),alpha=fade*fade;glowAt({x:s.x,y:s.y-15},r,col,alpha*.6);ctx.globalAlpha=fade*.8;groundRing(e.x,e.y,r,col,2);let n=Math.floor(13*count);for(let j=0;j<n;j++){let a=j/n*6.28+e.seed,rr=r*(.6+.35*Math.sin(j*17));let pos=project(e.x+Math.cos(a)*rr,e.y+Math.sin(a)*rr);ctx.strokeStyle=j%3===0?'#ffefd2':col;ctx.lineWidth=1.5;ctx.beginPath();ctx.moveTo(s.x+(pos.x-s.x)*.65,s.y+(pos.y-s.y)*.65-10);ctx.lineTo(pos.x,pos.y-10-Math.sin(t*3.14)*12);ctx.stroke()}if(e.style==='frost')for(let j=0;j<4*count;j++)iceShard(e.x+Math.cos(j*1.57)*r,e.y+Math.sin(j*1.57)*r,7*fade,j,fade*.45)}
if(e.type==='embers'){ctx.globalAlpha=fade;for(let j=0;j<18*count;j++){let a=j*2.4+e.seed,rr=e.r*t*(.4+(j%5)/5),pos=project(e.x+Math.cos(a)*rr,e.y+Math.sin(a)*rr);circle(pos.x,pos.y-t*(20+j%5*10),j%3===0?2:1,col)}}
if(e.type==='sigil'){ctx.globalAlpha=fade;groundRing(e.x,e.y,e.r*(.6+t*.6),col,2);let r=e.r*.8;ctx.strokeStyle=col;ctx.lineWidth=1;ctx.beginPath();for(let j=0;j<7;j++){let a=j*Math.PI/3+t,pt=project(e.x+Math.cos(a)*r,e.y+Math.sin(a)*r);j?ctx.lineTo(pt.x,pt.y):ctx.moveTo(pt.x,pt.y)}ctx.stroke()}
if(e.type==='muzzle')glowAt({x:s.x,y:s.y-20},35,col,fade*.8);
if(e.type==='ghost'){ctx.globalCompositeOperation='source-over';actorSprite(heroSheet,e.x,e.y,100,'walk',.15,e.facing,fade*.24);ctx.globalCompositeOperation='lighter'}}
for(let z of zonesFx){if(z.kind==='bolt'){let from=project(z.x,z.y),to=project(z.tx,z.ty),fade=Math.min(1,z.life*4);ctx.globalAlpha=fade;ctx.shadowColor='#8d96ff';ctx.shadowBlur=effectQuality==='low'?0:12;for(let layer=0;layer<2;layer++){ctx.strokeStyle=layer?'#eff5ff':'#7889f9';ctx.lineWidth=layer?1.5:5;ctx.beginPath();ctx.moveTo(from.x,from.y-22);for(let j=1;j<=12;j++){let t=j/12,offset=j===12?0:Math.sin(j*7.3+clock*35)*12;ctx.lineTo(from.x+(to.x-from.x)*t+offset,from.y+(to.y-from.y)*t-22+offset*.4)}ctx.stroke()}ctx.shadowBlur=0;for(let j=1;j<4*count;j++){let t=j/4,x=from.x+(to.x-from.x)*t,y=from.y+(to.y-from.y)*t-22;ctx.strokeStyle='#9fb2f7';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x+Math.sin(j*4+clock)*25,y-20);ctx.lineTo(x+Math.sin(j*4+clock)*35,y-35);ctx.stroke()}}
if(z.kind==='vortex'){ctx.globalAlpha=Math.min(1,z.life);let n=Math.floor(5*count);for(let arm=0;arm<n;arm++){ctx.strokeStyle=arm%2?'#c69cf8':'#6f63b4';ctx.lineWidth=2;ctx.beginPath();for(let j=0;j<50;j++){let t=j/49,a=arm*Math.PI*2/n+t*6.28-clock*3,r=z.r*t,pt=project(z.x+Math.cos(a)*r,z.y+Math.sin(a)*r);j?ctx.lineTo(pt.x,pt.y):ctx.moveTo(pt.x,pt.y)}ctx.stroke()}let c=project(z.x,z.y);glowAt(c,50,'#bc8df8',.25)}}ctx.restore()}
const simpleEffects=drawEffects;drawEffects=()=>{simpleEffects();paintDeluxeEffects()};


